import type { DragEvent } from 'react';

export type Priority = 'high' | 'medium' | 'low';

export type ColumnType = 'todo' | 'in_progress' | 'done';

export interface Task {
  id: string;
  title: string;
  description: string;
  status: ColumnType;
  priority: Priority;
  assignee: string;
  dueDate: string;
}

export interface ColumnData {
  id: ColumnType;
  title: string;
}

export interface TaskFormData {
  title: string;
  description: string;
  status: ColumnType;
  priority: Priority;
  assignee: string;
  dueDate: string;
}

export interface TaskCardProps {
  task: Task;
  onDragStart: (e: DragEvent, id: string) => void;
  onEdit: (task: Task) => void;
  onDelete: (id: string) => void;
  onMoveStatus: (id: string, nextStatus: ColumnType) => void;
}

export interface ColumnProps {
  column: ColumnData;
  tasks: Task[];
  isDraggingOver: boolean;
  onDragOver: (e: DragEvent) => void;
  onDragLeave: () => void;
  onDrop: (e: DragEvent, status: ColumnType) => void;
  onDragStart: (e: DragEvent, id: string) => void;
  onAddTask: (status: ColumnType) => void;
  onEditTask: (task: Task) => void;
  onDeleteTask: (id: string) => void;
  onMoveStatus: (id: string, nextStatus: ColumnType) => void;
}

export interface TaskModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (data: TaskFormData, editId?: string) => void;
  initialTask: Task | null;
  defaultStatus: ColumnType;
}

import { useState } from 'react';
import type { DragEvent } from 'react';
import { Calendar, User, Edit2, Trash2, ChevronLeft, ChevronRight } from 'lucide-react';
import type { TaskCardProps, ColumnType } from '../types';

export default function TaskCard({
  task,
  onDragStart,
  onEdit,
  onDelete,
  onMoveStatus,
}: TaskCardProps) {
  const [isDragging, setIsDragging] = useState(false);

  const handleDragStart = (e: DragEvent<HTMLDivElement>) => {
    setIsDragging(true);
    onDragStart?.(e, task.id);
  };

  const handleDragEnd = () => {
    setIsDragging(false);
  };

  const getPriorityLabel = (priority: string) => {
    switch (priority) {
      case 'high':
        return '高';
      case 'medium':
        return '中';
      case 'low':
        return '低';
      default:
        return priority;
    }
  };

  const getPriorityClass = (priority: string) => {
    switch (priority) {
      case 'high':
        return 'priority-high';
      case 'medium':
        return 'priority-medium';
      case 'low':
        return 'priority-low';
      default:
        return 'priority-medium';
    }
  };

  return (
    <div
      className={`task-card ${isDragging ? 'task-card-dragging' : ''}`}
      draggable
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
    >
      <div className="task-card-header">
        <span className={`task-priority-badge ${getPriorityClass(task.priority)}`}>
          優先度: {getPriorityLabel(task.priority)}
        </span>
        <div className="task-actions">
          <button
            type="button"
            className="btn-icon"
            onClick={() => onEdit?.(task)}
            title="タスクを編集"
            aria-label="タスクを編集"
          >
            <Edit2 size={15} />
          </button>
          <button
            type="button"
            className="btn-icon"
            onClick={() => onDelete?.(task.id)}
            title="タスクを削除"
            aria-label="タスクを削除"
          >
            <Trash2 size={15} />
          </button>
        </div>
      </div>

      <h4 className="task-title">{task.title}</h4>

      {task.description && (
        <p className="task-description">{task.description}</p>
      )}

      <div className="task-card-footer">
        {task.dueDate && (
          <div className="task-meta-item" title="期日">
            <Calendar size={13} />
            <span>{task.dueDate}</span>
          </div>
        )}
        {task.assignee && (
          <div className="task-meta-item" title="担当者">
            <User size={13} />
            <span>{task.assignee}</span>
          </div>
        )}
      </div>

      <div className="task-mobile-nav">
        {task.status !== 'todo' && (
          <button
            type="button"
            className="task-nav-btn"
            onClick={() => {
              const prevStatus: ColumnType =
                task.status === 'done' ? 'in_progress' : 'todo';
              onMoveStatus?.(task.id, prevStatus);
            }}
            title="前のステータスへ移動"
          >
            <ChevronLeft size={14} />
            <span>前へ</span>
          </button>
        )}

        {task.status !== 'done' && (
          <button
            type="button"
            className="task-nav-btn"
            onClick={() => {
              const nextStatus: ColumnType =
                task.status === 'todo' ? 'in_progress' : 'done';
              onMoveStatus?.(task.id, nextStatus);
            }}
            title="次のステータスへ移動"
            style={{ marginLeft: 'auto' }}
          >
            <span>次へ</span>
            <ChevronRight size={14} />
          </button>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import type { FormEvent, MouseEvent } from 'react';
import { X } from 'lucide-react';
import type { TaskModalProps, TaskFormData, Priority, ColumnType } from '../types';

export default function TaskModal({
  isOpen,
  onClose,
  onSave,
  initialTask,
  defaultStatus,
}: TaskModalProps) {
  const [formData, setFormData] = useState<TaskFormData>({
    title: '',
    description: '',
    status: 'todo',
    priority: 'medium',
    assignee: '',
    dueDate: '',
  });

  useEffect(() => {
    if (initialTask) {
      setFormData({
        title: initialTask.title,
        description: initialTask.description,
        status: initialTask.status,
        priority: initialTask.priority,
        assignee: initialTask.assignee,
        dueDate: initialTask.dueDate,
      });
    } else {
      setFormData({
        title: '',
        description: '',
        status: defaultStatus || 'todo',
        priority: 'medium',
        assignee: '',
        dueDate: new Date().toISOString().substring(0, 10),
      });
    }
  }, [initialTask, defaultStatus, isOpen]);

  if (!isOpen) return null;

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!formData.title.trim()) return;

    onSave?.(formData, initialTask ? initialTask.id : undefined);
    onClose?.();
  };

  const handleBackdropClick = (e: MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget) {
      onClose?.();
    }
  };

  return (
    <div className="modal-backdrop" onClick={handleBackdropClick}>
      <div className="modal-content" role="dialog" aria-modal="true">
        <div className="modal-header">
          <h3 className="modal-title">
            {initialTask ? 'タスクを編集' : '新しいタスクを作成'}
          </h3>
          <button
            type="button"
            className="modal-close-btn"
            onClick={onClose}
            aria-label="閉じる"
          >
            <X size={18} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="modal-form">
          <div className="form-group">
            <label className="form-label" htmlFor="task-title-input">
              タイトル <span style={{ color: '#ef4444' }}>*</span>
            </label>
            <input
              id="task-title-input"
              className="form-input"
              type="text"
              required
              placeholder="例: ホームページのデザインリニューアル"
              value={formData.title}
              onChange={(e) =>
                setFormData({ ...formData, title: e.target.value })
              }
            />
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="task-desc-input">
              説明・詳細
            </label>
            <textarea
              id="task-desc-input"
              className="form-textarea"
              rows={3}
              placeholder="タスクの要件や目的、注意点を記入してください"
              value={formData.description}
              onChange={(e) =>
                setFormData({ ...formData, description: e.target.value })
              }
            />
          </div>

          <div className="form-row">
            <div className="form-group">
              <label className="form-label" htmlFor="task-status-select">
                ステータス
              </label>
              <select
                id="task-status-select"
                className="form-select"
                value={formData.status}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    status: e.target.value as ColumnType,
                  })
                }
              >
                <option value="todo">未着手</option>
                <option value="in_progress">作業中</option>
                <option value="done">完了</option>
              </select>
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="task-priority-select">
                優先度
              </label>
              <select
                id="task-priority-select"
                className="form-select"
                value={formData.priority}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    priority: e.target.value as Priority,
                  })
                }
              >
                <option value="high">高</option>
                <option value="medium">中</option>
                <option value="low">低</option>
              </select>
            </div>
          </div>

          <div className="form-row">
            <div className="form-group">
              <label className="form-label" htmlFor="task-assignee-input">
                担当者
              </label>
              <input
                id="task-assignee-input"
                className="form-input"
                type="text"
                placeholder="例: 田中 太郎"
                value={formData.assignee}
                onChange={(e) =>
                  setFormData({ ...formData, assignee: e.target.value })
                }
              />
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="task-due-input">
                期日
              </label>
              <input
                id="task-due-input"
                className="form-input"
                type="date"
                value={formData.dueDate}
                onChange={(e) =>
                  setFormData({ ...formData, dueDate: e.target.value })
                }
              />
            </div>
          </div>

          <div className="modal-footer">
            <button
              type="button"
              className="btn btn-secondary"
              onClick={onClose}
            >
              キャンセル
            </button>
            <button type="submit" className="btn btn-primary">
              {initialTask ? '変更を保存' : 'タスクを追加'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

import { Plus } from 'lucide-react';
import type { ColumnProps } from '../types';
import TaskCard from './TaskCard';

export default function Column({
  column,
  tasks = [],
  isDraggingOver,
  onDragOver,
  onDragLeave,
  onDrop,
  onDragStart,
  onAddTask,
  onEditTask,
  onDeleteTask,
  onMoveStatus,
}: ColumnProps) {
  return (
    <section
      className={`kanban-column ${isDraggingOver ? 'column-drag-over' : ''}`}
      onDragOver={onDragOver}
      onDragLeave={onDragLeave}
      onDrop={(e) => onDrop?.(e, column.id)}
    >
      <div className="column-header">
        <div className="column-title-group">
          <h3>{column.title}</h3>
          <span className="column-badge">{tasks.length}</span>
        </div>
        <button
          type="button"
          className="column-add-btn"
          onClick={() => onAddTask?.(column.id)}
          title={`${column.title}にタスクを追加`}
          aria-label={`${column.title}にタスクを追加`}
        >
          <Plus size={16} />
        </button>
      </div>

      <div className="task-list">
        {tasks.length === 0 ? (
          <div className="empty-column-placeholder">
            <span>タスクがありません</span>
          </div>
        ) : (
          tasks.map((task) => (
            <TaskCard
              key={task.id}
              task={task}
              onDragStart={onDragStart}
              onEdit={onEditTask}
              onDelete={onDeleteTask}
              onMoveStatus={onMoveStatus}
            />
          ))
        )}
      </div>
    </section>
  );
}

import { useState } from 'react';
import type { DragEvent } from 'react';
import { Plus, Search } from 'lucide-react';
import type { Task, ColumnData, ColumnType, TaskFormData } from './types';
import Column from './components/Column';
import TaskModal from './components/TaskModal';

const INITIAL_COLUMNS: ColumnData[] = [
  { id: 'todo', title: '未着手' },
  { id: 'in_progress', title: '作業中' },
  { id: 'done', title: '完了' },
];

const INITIAL_TASKS: Task[] = [
  {
    id: 'task-1',
    title: 'トップページのUIデザイン作成',
    description: 'Figmaで新規ランディングページのモックアップを作成し、チームレビューを行う',
    status: 'todo',
    priority: 'high',
    assignee: '佐藤 健太',
    dueDate: '2025-04-10',
  },
  {
    id: 'task-2',
    title: '認証機能のAPI連携',
    description: 'JWTトークンを用いたユーザー認証と権限チェックエンドポイントの接続',
    status: 'todo',
    priority: 'medium',
    assignee: '鈴木 美穂',
    dueDate: '2025-04-14',
  },
  {
    id: 'task-3',
    title: 'アクセシビリティチェック',
    description: 'WAI-ARIA属性の適合性確認およびスクリーンリーダーでの動作確認',
    status: 'todo',
    priority: 'low',
    assignee: '高橋 雄大',
    dueDate: '2025-04-20',
  },
  {
    id: 'task-4',
    title: 'ドラッグ＆ドロップ機能の実装',
    description: 'HTML5 Drag & Drop APIを利用したスムーズなカード移動の構築',
    status: 'in_progress',
    priority: 'high',
    assignee: '田中 太郎',
    dueDate: '2025-04-08',
  },
  {
    id: 'task-5',
    title: 'ダークモード対応CSSの調整',
    description: 'カラーパレットの変数を再構成し、各テーマごとのコントラスト比を検証',
    status: 'in_progress',
    priority: 'medium',
    assignee: '渡辺 奈緒',
    dueDate: '2025-04-12',
  },
  {
    id: 'task-6',
    title: 'レスポンシブ表示の崩れ修正',
    description: 'スマートフォン幅（360px以下）でのモーダルおよびカラムのパディング調整',
    status: 'in_progress',
    priority: 'high',
    assignee: '田中 太郎',
    dueDate: '2025-04-09',
  },
  {
    id: 'task-7',
    title: '初期プロジェクト設計書の作成',
    description: 'コンポーネント構成図と状態管理設計、ディレクトリ階層を文書化',
    status: 'done',
    priority: 'medium',
    assignee: '伊藤 翼',
    dueDate: '2025-04-02',
  },
  {
    id: 'task-8',
    title: '型定義と基本スタイルの策定',
    description: 'TypeScriptインターフェースとグローバルCSSの共通クラス定義',
    status: 'done',
    priority: 'low',
    assignee: '佐藤 健太',
    dueDate: '2025-04-03',
  },
];

export default function App() {
  const [tasks, setTasks] = useState<Task[]>(INITIAL_TASKS);
  const [searchQuery, setSearchQuery] = useState('');
  const [draggedTaskId, setDraggedTaskId] = useState<string | null>(null);
  const [dragOverColumn, setDragOverColumn] = useState<ColumnType | null>(null);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [defaultStatus, setDefaultStatus] = useState<ColumnType>('todo');

  const handleDragStart = (e: DragEvent, id: string) => {
    setDraggedTaskId(id);
    e.dataTransfer.setData('text/plain', id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: DragEvent, columnId: ColumnType) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    if (dragOverColumn !== columnId) {
      setDragOverColumn(columnId);
    }
  };

  const handleDragLeave = () => {
    setDragOverColumn(null);
  };

  const handleDrop = (e: DragEvent, targetStatus: ColumnType) => {
    e.preventDefault();
    setDragOverColumn(null);
    const taskId = e.dataTransfer.getData('text/plain') || draggedTaskId;

    if (taskId) {
      setTasks((prevTasks) =>
        prevTasks.map((t) =>
          t.id === taskId ? { ...t, status: targetStatus } : t
        )
      );
    }
    setDraggedTaskId(null);
  };

  const handleMoveStatus = (id: string, nextStatus: ColumnType) => {
    setTasks((prevTasks) =>
      prevTasks.map((t) => (t.id === id ? { ...t, status: nextStatus } : t))
    );
  };

  const handleOpenAddModal = (status: ColumnType = 'todo') => {
    setEditingTask(null);
    setDefaultStatus(status);
    setIsModalOpen(true);
  };

  const handleOpenEditModal = (task: Task) => {
    setEditingTask(task);
    setDefaultStatus(task.status);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setEditingTask(null);
  };

  const handleSaveTask = (formData: TaskFormData, editId?: string) => {
    if (editId) {
      setTasks((prevTasks) =>
        prevTasks.map((t) => (t.id === editId ? { ...t, ...formData } : t))
      );
    } else {
      const newTask: Task = {
        id: `task-${Date.now()}`,
        ...formData,
      };
      setTasks((prevTasks) => [newTask, ...prevTasks]);
    }
  };

  const handleDeleteTask = (id: string) => {
    setTasks((prevTasks) => prevTasks.filter((t) => t.id !== id));
  };

  const filteredTasks = tasks.filter((task) => {
    const query = searchQuery.trim().toLowerCase();
    if (!query) return true;
    return (
      task.title.toLowerCase().includes(query) ||
      task.description.toLowerCase().includes(query) ||
      task.assignee.toLowerCase().includes(query)
    );
  });

  return (
    <div className="app-container">
      <header className="board-header">
        <div className="header-title-wrap">
          <h1 className="header-title">プロジェクト カンバンボード</h1>
          <p className="header-subtitle">
            カードをドラッグ＆ドロップしてタスクの進捗状況を素早く更新できます
          </p>
        </div>

        <div className="header-actions">
          <div style={{ position: 'relative', display: 'flex', alignItems: 'center' }}>
            <Search
              size={16}
              style={{
                position: 'absolute',
                left: '12px',
                color: '#94a3b8',
                pointerEvents: 'none',
              }}
            />
            <input
              type="text"
              className="board-search-input"
              placeholder="タスク・担当者を検索..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              style={{ paddingLeft: '36px' }}
            />
          </div>

          <button
            type="button"
            className="btn btn-primary"
            onClick={() => handleOpenAddModal('todo')}
          >
            <Plus size={16} />
            <span>タスクを追加</span>
          </button>
        </div>
      </header>

      <main className="board-columns">
        {INITIAL_COLUMNS.map((column) => {
          const columnTasks = filteredTasks.filter(
            (t) => t.status === column.id
          );
          return (
            <Column
              key={column.id}
              column={column}
              tasks={columnTasks}
              isDraggingOver={dragOverColumn === column.id}
              onDragOver={(e) => handleDragOver(e, column.id)}
              onDragLeave={handleDragLeave}
              onDrop={handleDrop}
              onDragStart={handleDragStart}
              onAddTask={handleOpenAddModal}
              onEditTask={handleOpenEditModal}
              onDeleteTask={handleDeleteTask}
              onMoveStatus={handleMoveStatus}
            />
          );
        })}
      </main>

      <TaskModal
        isOpen={isModalOpen}
        onClose={handleCloseModal}
        onSave={handleSaveTask}
        initialTask={editingTask}
        defaultStatus={defaultStatus}
      />
    </div>
  );
}
